using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes active state for a username of the current user. The editable username can't be disabled. May return an error with a message "USERNAMES_ACTIVE_TOO_MUCH" if the maximum number of active usernames has been reached
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ToggleUsernameIsActiveAsync(string username = default, bool isActive = default)
    {

           using var activity =  StartCallActivity("ToggleUsernameIsActiveAsync", typeof(ToggleUsernameIsActive).FullName ?? "ToggleUsernameIsActiveAsync");

           try
           {
             return client.ToggleUsernameIsActiveAsync(username, isActive);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
